MARCA = {"fanuc_focas.py": "def leer_alarmas", "monitor.py": "def procesar_alarmas", "templates/monitor.html": "function alarmasDe"}
base = sys.argv[1] if len(sys.argv) > 1 else os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
if not os.path.exists(os.path.join(base, "monitor.py")):
    base = os.getcwd()
nuevos = {}
for f, pares in PARES.items():
    p = os.path.join(base, f)
    txt = open(p, encoding="utf-8", newline="").read()
    crlf = "\r\n" in txt
    t = txt.replace("\r\n", "\n")
    if MARCA[f] in t:
        print("Ya aplicado:", f); continue
    for viejo, nuevo in pares:
        if t.count(viejo) != 1:
            print("ERROR: el archivo", f, "es distinto del esperado; no se cambió nada.")
            print("No encontré este bloque:\n" + viejo[:300]); sys.exit(1)
        t = t.replace(viejo, nuevo)
    nuevos[p] = t.replace("\n", "\r\n") if crlf else t
for p, t in nuevos.items():
    shutil.copy2(p, p + ".bak_alarmas_20261113")
    open(p, "w", encoding="utf-8", newline="").write(t)
    print("Actualizado:", p)
print("Listo. Cerrá Nexus y abrilo de nuevo.")
